import requests
from bs4 import BeautifulSoup
import re

# Search for Collins Spanish-English dictionary entries for 'caminata'
urls = [
    'https://www.collinsdictionary.com/dictionary/spanish-english/caminata',
    'https://www.collinsdictionary.com/us/dictionary/spanish-english/caminata',
    'https://www.collinsdictionary.com/dictionary/english-spanish/caminata'
]

print('Searching Collins dictionary for caminata...')
for url in urls:
    try:
        response = requests.get(url, headers={'User-Agent': 'Mozilla/5.0'})
        if response.status_code == 200:
            soup = BeautifulSoup(response.text, 'html.parser')
            print(f'✅ Successfully accessed: {url}')

            # Look for content related to caminata
            title = soup.find('title')
            if title:
                print(f'Page title: {title.get_text()}')

            # Look for dictionary entries
            entries = soup.find_all('div', class_='dictionary_entry')
            if entries:
                print(f'Found {len(entries)} dictionary entries')
                for i, entry in enumerate(entries[:3]):  # Show first 3 entries
                    print(f'Entry {i+1}:')
                    word = entry.find('span', class_='orth')
                    if word:
                        print(f'  Word: {word.get_text()}')
                    definition = entry.find('div', class_='def')
                    if definition:
                        print(f'  Definition: {definition.get_text()[:200]}...')

                    # Look for examples, especially from 1994
                    examples = entry.find_all('span', class_='quote')
                    if examples:
                        print(f'  Examples found: {len(examples)}')
                        for j, example in enumerate(examples[:2]):
                            example_text = example.get_text()
                            if '1994' in example_text:
                                print(f'    📅 1994 Example: {example_text[:100]}...')

                    print()
            else:
                print('No dictionary entries found with standard class names')

            # Look for any mention of 1994
            if '1994' in response.text:
                print('📅 Found 1994 mention in page')
                # Extract context around 1994
                lines = response.text.split('\n')
                for i, line in enumerate(lines):
                    if '1994' in line:
                        print(f'Context: {lines[max(0,i-2):i+3]}')
                        break
        else:
            print(f'❌ Failed to access {url} - Status: {response.status_code}')
    except Exception as e:
        print(f'❌ Error accessing {url}: {str(e)}')
    print()
