import requests
from bs4 import BeautifulSoup
import re

# Get detailed content from SpanishDict and WordReference focusing on examples and 1994

urls = [
    'https://www.spanishdict.com/translate/caminata',
    'https://www.wordreference.com/es/en/translation.asp?spen=caminata',
    'https://www.linguee.com/spanish-english/translation/caminata.html'
]

print('Detailed extraction of caminata content with focus on 1994 examples...')
for url in urls:
    try:
        response = requests.get(url, headers={'User-Agent': 'Mozilla/5.0'})
        if response.status_code == 200:
            soup = BeautifulSoup(response.text, 'html.parser')
            print(f'\\n=== {url} ===')

            # Look for 1994 specifically
            if '1994' in response.text:
                print('📅 FOUND 1994 CONTENT!')
                # Extract all lines containing 1994
                lines = response.text.split('\n')
                for i, line in enumerate(lines):
                    if '1994' in line:
                        print(f'Line {i}: {line.strip()}')
                        # Show context
                        for j in range(max(0, i-2), min(len(lines), i+3)):
                            marker = '>>>' if j == i else '   '
                            print(f'{marker} {lines[j].strip()[:150]}...')
                        print()
            else:
                print('📅 No 1994 content found')

            # Look for dictionary entries and examples
            if 'spanishdict.com' in url:
                # SpanishDict structure
                examples = soup.find_all('div', class_='example')
                if examples:
                    print(f'Found {len(examples)} examples on SpanishDict:')
                    for i, example in enumerate(examples[:5]):
                        text = example.get_text()
                        if '1994' in text:
                            print(f'📅 1994 Example {i+1}: {text[:200]}...')
                        else:
                            print(f'Example {i+1}: {text[:200]}...')

            elif 'wordreference.com' in url:
                # WordReference structure
                examples = soup.find_all('div', class_='example')
                if examples:
                    print(f'Found {len(examples)} examples on WordReference:')
                    for i, example in enumerate(examples[:5]):
                        text = example.get_text()
                        if '1994' in text:
                            print(f'📅 1994 Example {i+1}: {text[:200]}...')
                        else:
                            print(f'Example {i+1}: {text[:200]}...')

            elif 'linguee.com' in url:
                # Linguee structure
                examples = soup.find_all('div', class_='example')
                if examples:
                    print(f'Found {len(examples)} examples on Linguee:')
                    for i, example in enumerate(examples[:5]):
                        text = example.get_text()
                        if '1994' in text:
                            print(f'📅 1994 Example {i+1}: {text[:200]}...')
                        else:
                            print(f'Example {i+1}: {text[:200]}...')

            # Look for any source citations
            sources = soup.find_all(text=re.compile(r'(source|citation|reference|1994)', re.IGNORECASE))
            if sources:
                print('\\nPossible source references:')
                for source in sources[:10]:
                    source_text = source.strip()
                    if len(source_text) > 10:
                        print(f'  - {source_text[:150]}...')

    except Exception as e:
        print(f'❌ Error processing {url}: {str(e)}')
""}

