        if response.status_code == 200:
            soup = BeautifulSoup(response.text, 'html.parser')
            print(f'✅ Archive access: {url}')

            # Look for any mention of Collins or dictionary content
            content = soup.get_text()
            if any(term in content.lower() for term in ['collins', 'dictionary', 'caminata']):
                print('Found relevant archive content')

                if '1994' in content:
                    print('📅 Found 1994 content in archive!')
                    # Extract lines with 1994
                    lines = content.split('\n')
                    for i, line in enumerate(lines):
                        if '1994' in line:
                            print(f'Archive line {i}: {line.strip()}')
                            # Show context
                            for j in range(max(0, i-1), min(len(lines), i+2)):
                                marker = '>>>' if j == i else '   '
                                print(f'{marker} {lines[j].strip()[:150]}...')
                            print()
                else:
                    print('No 1994 content found in this archive')
        else:
            print(f'❌ Archive access failed: {url} - Status: {response.status_code}')
    except Exception as e:
        print(f'❌ Error accessing archive {url}: {str(e)}')
    print()

# Try searching for specific Collins dictionary references
